(() => {
 const wrap=(kind,title,sub,content)=>{const el=document.createElement('section');el.className='math-visual visual-'+kind;el.innerHTML=`<header class="visual-head"><div><div class="visual-kicker">数学图解</div><h3>${title}</h3></div><span>${sub}</span></header>${content}`;return el};
 const svg=(body,w=640,h=175)=>`<svg viewBox="0 0 ${w} ${h}" role="img" xmlns="http://www.w3.org/2000/svg">${body}</svg>`;
 const tx=(x,y,t,cls='',a='middle')=>`<text x="${x}" y="${y}" class="${cls}" text-anchor="${a}">${t}</text>`;
 const line=(x,y,X,Y,cls='axis')=>`<path d="M${x} ${y} L${X} ${Y}" class="${cls}"/>`;
 const path=(fn,xlo,xhi,px,py)=>Array.from({length:161},(_,i)=>{let x=xlo+(xhi-xlo)*i/160;return `${i?'L':'M'}${px(x).toFixed(2)} ${py(fn(x)).toFixed(2)}`}).join(' ');
 function mini(fn,range,yrange,title,foot){let [a,b]=range,[c,d]=yrange;const px=x=>26+(x-a)/(b-a)*250,py=y=>12+(d-y)/(d-c)*124;return `<div class="mini-plot"><div class="mini-title">${title}</div>${svg(line(px(0),12,px(0),136)+line(26,py(0),276,py(0))+`<path d="${path(fn,a,b,px,py)}" class="curve"/><circle cx="${px(0)}" cy="${py(0)}" r="4" class="dot"/>`,300,148)}<p>${foot}</p></div>`}
 function sign(g=true){const pts=g?['−1','2']:['−1','1'];return wrap('sign','导数符号 → 曲线走势','从左向右读',`<div class="sign-grid"><span class="sg-key">区间</span><span>x &lt; ${pts[0]}</span><span>${pts[0]} &lt; x &lt; ${pts[1]}</span><span>x &gt; ${pts[1]}</span><span class="sg-key">导数</span><b class="rise">＋</b><b class="fall">−</b><b class="rise">＋</b><span class="sg-key">函数</span><span class="rise">↗ 递增</span><span class="fall">↘ 递减</span><span class="rise">↗ 递增</span></div><div class="sign-peaks"><span><i></i> ${pts[0]}：极大值点</span><span><i></i> ${pts[1]}：极小值点</span></div>`)}
 function near(){let px=x=>52+(x+1.35)/.7*530,py=y=>142-(y-6.7)*87;let f=x=>2*x**3-3*x*x-12*x+1;return wrap('near','只观察 x = −1 附近','候选点 ≠ 极小值点',svg(`<rect x="35" y="12" width="285" height="140" rx="8" class="zone-rise"/><rect x="320" y="12" width="285" height="140" rx="8" class="zone-fall"/>`+line(52,142,582,142)+line(320,12,320,144,'dashed')+`<path class="curve" d="${path(f,-1.35,-.65,px,py)}"/><circle class="dot" cx="320" cy="${py(8)}" r="5"/>`+tx(175,32,'g′ > 0','rise')+tx(466,32,'g′ < 0','fall')+tx(320,164,'−1','label')+tx(175,128,'向右上升','rise')+tx(466,128,'向右下降','fall'),640,177))}
 function tree(){return wrap('tree','不放回抽球：两条通往红球的路径','路径相乘，再相加',svg(`<g class="tree-lines">${line(100,95,278,45)}${line(100,95,278,145)}${line(338,45,510,45,'tree-highlight')}${line(338,145,510,145,'tree-highlight')}</g>`+`<rect x="25" y="75" width="95" height="40" rx="10" class="neutral-node"/><rect x="250" y="25" width="100" height="40" rx="10" class="red-node"/><rect x="250" y="125" width="100" height="40" rx="10" class="blue-node"/><rect x="494" y="25" width="115" height="40" rx="10" class="red-node"/><rect x="494" y="125" width="115" height="40" rx="10" class="red-node"/>`+tx(72,100,'3 红 · 2 蓝')+tx(300,50,'第一次红')+tx(300,150,'第一次蓝')+tx(552,50,'第二次红')+tx(552,150,'第二次红')+tx(190,60,'3/5','label')+tx(190,140,'2/5','label')+tx(425,35,'2/4','label')+tx(425,135,'3/4','label'),640,192)+`<div class="tree-footer"><span>先红后红：3/10</span><span>先蓝后红：3/10</span></div>`)}
 function conic(sw=false){const grid=(body,title,desc)=>`<div class="mini-plot"><div class="mini-title">${title}</div>${svg(line(18,78,282,78)+line(150,8,150,148)+body,300,156)}<p>${desc}</p></div>`;let ell=(rx,ry,pts)=>`<ellipse cx="150" cy="78" rx="${rx}" ry="${ry}" class="curve"/>`+pts.map(([x,y])=>`<circle class="dot" cx="${x}" cy="${y}" r="4"/>`).join('');let hyper=[-1,1].map(sign=>`<path class="curve" d="${Array.from({length:81},(_,i)=>{let t=-1.25+i*2.5/80;return `${i?'L':'M'}${150+sign*60*Math.cosh(t)} ${78-36*Math.sinh(t)}`}).join(' ')}"/>`).join('');return wrap(sw?'ellipse':'conic',sw?'长轴转向，离心率不变':'同一组分母，两种不同曲线',sw?'焦点随长轴移动':'看平方项间的符号',`<div class="mini-grid">${grid(ell(60,36,[[102,78],[198,78]]),'x²/25 + y²/9 = 1',sw?'焦点 (±4, 0)':'闭合的椭圆')}${sw?grid(ell(36,60,[[150,30],[150,126]]),'x²/9 + y²/25 = 1','焦点 (0, ±4)'):grid(hyper,'x²/25 − y²/9 = 1','向两侧无限延伸')}</div>`)}
 window.V6_VISUALS={create(kind){if(kind==='sign-g')return sign();if(kind==='near-max')return near();if(kind==='probability-tree')return tree();if(kind==='conic-compare')return conic();if(kind==='ellipse-swap')return conic(true);if(kind==='compare-flat')return wrap('comparison','同样水平切线，不同局部形状','对照原点两侧',`<div class="mini-grid">${mini(x=>x*x*x,[-1.2,1.2],[-1.8,1.8],'f(x) = x³','左正 → 右正 · 不是极值')}${mini(x=>x*x,[-1.2,1.2],[-.3,1.6],'f(x) = x²','左负 → 右正 · 局部极小')}</div>`);return document.createElement('div')}};
})();
